/**
 * Concept: the sentences of L(G) up to a length k, generated by a breadth-first search over
 * leftmost sentential forms. Every bounded search of step 27 starts from this list.
 * Reference: Hopcroft 5.1 and 7.4.3; SPEC 02, section 3.25.
 * Card: docs/concepts/25-bounded-searches.md
 */
import { computeMinYield, minYieldOfSequence } from '../analysis/min-yield.js';
import type { Grammar, SymbolName } from '../grammar/types.js';

/** By default the search gives up after this many sentential forms. */
export const DEFAULT_MAX_FORMS = 500_000;

/**
 * Every sentence of L(G) with at most maxLength tokens, without repeats, shortest first and
 * then in lexicographic order. Throws if the search explores more than maxForms forms, which
 * only happens with a recursion that adds no tokens (S → S B with B ⇒ ε).
 */
export function generateSentences({
  grammar,
  maxLength,
  maxForms = DEFAULT_MAX_FORMS,
}: {
  grammar: Grammar;
  /** k: the longest sentence to generate. */
  maxLength: number;
  /** The most sentential forms to explore before giving up. */
  maxForms?: number | undefined;
}): SymbolName[][] {
  // Each form is a step of a leftmost derivation from S: expanding its leftmost
  // nonterminal in every possible way gives the next forms. A form whose minYield is
  // already longer than k can never become a sentence of length ≤ k, so it is dropped;
  // a form seen before is not explored again. When a form has no nonterminal left, it is
  // a sentence.
  const minYield = computeMinYield(grammar);
  const start = [grammar.start];
  const queue: SymbolName[][] = [start];
  const visited = new Set([start.join(' ')]);
  const sentences = new Map<string, SymbolName[]>();
  for (let next = 0; next < queue.length; next++) {
    if (next >= maxForms) {
      throw new Error(
        `generateSentences explored ${maxForms} forms without finishing: the grammar grows without adding tokens`,
      );
    }
    const form = queue[next] ?? [];
    const position = form.findIndex((symbol) => grammar.nonterminals.has(symbol));
    if (position === -1) {
      sentences.set(form.join(' '), form);
      continue;
    }
    for (const production of grammar.productionsByLeftSide.get(form[position] ?? '') ?? []) {
      const expanded = [
        ...form.slice(0, position),
        ...production.rightSide,
        ...form.slice(position + 1),
      ];
      const key = expanded.join(' ');
      if (!visited.has(key) && minYieldOfSequence({ symbols: expanded, minYield }) <= maxLength) {
        visited.add(key);
        queue.push(expanded);
      }
    }
  }
  return [...sentences.values()].sort(compareSentences);
}

/** Shortest first; between two of the same length, the first different token decides. */
export function compareSentences(
  first: readonly SymbolName[],
  second: readonly SymbolName[],
): number {
  if (first.length !== second.length) {
    return first.length - second.length;
  }
  const index = first.findIndex((token, position) => token !== second[position]);
  if (index === -1) {
    return 0;
  }
  return (first[index] ?? '') < (second[index] ?? '') ? -1 : 1;
}
